pub fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    let mut evens = Vec::with_capacity(arr.len());
    for &x in arr {
        if x % 2 == 0 {
            evens.push(x);
        }
    }
    evens
}

